def insert_answer(kind,num,figure):
    global s
    pat=rf'(<details class="answer" data-kind="{kind}" data-q="{num}">.*?<div class="answer-body">)(.*?)(</div></details>)'
    s,n=re.subn(pat,lambda m:m[1]+m[2]+figure+m[3],s,count=1,flags=re.S)
    assert n==1,(kind,num)
